//////
// some odd noise.
// in the movement, you can almost...
// ... see the lattice of... dimension.

#define REWIND -45.0
#define SLOW 0.5
#define FADE 0.01

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    float time = iTime + sin(iTime * SLOW) * (fragCoord.x / fragCoord.y);
    float seed = REWIND + time;

    uv = pow(uv, vec2(uv * seed));
    uv.x = sin(uv.x) / uv.x;
    uv.y = cos(uv.y) / uv.x;
    uv /= seed;
    float col = clamp(uv.y * FADE, 0.0, 0.4);
    fragColor = vec4(vec3(col), 1.0);
}

